package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.session.SessionSnapshot;
import java.util.List;
import java.util.concurrent.Flow;

/** Thread-safe Session entry point. A Session permits at most one active Run. */
public interface AgentSession extends AutoCloseable {
    String id();
    AgentRun prompt(String text);
    AgentRun prompt(String runId, String text);
    AgentRun resume();
    AgentCompaction compact();
    AgentCompaction compact(String customInstructions);
    AgentCompaction resumeCompaction();
    boolean hasActiveRun();
    SessionSnapshot snapshot();
    List<Message> transcript();
    Flow.Publisher<AgentEvent> events();
    boolean abort();

    @Override
    void close();
}
